def family_init(ctx):
    import math, bisect
    bars = ctx.bars
    n = len(bars)
    s = []
    for b in bars:
        x = float(b["c"])
        s.append(math.log(x) if x > 0.0 else 0.0)

    lv = int(ctx.p.levels)
    wave = str(ctx.p.wave)
    det = {}
    for j in range(1, lv + 1):
        sh = 1 << (j - 1)
        cur = [0.0] * n
        if wave == "b3":
            for t in range(n):
                a0 = s[t]
                a1 = s[t - sh] if t >= sh else s[0]
                a2 = s[t - 2 * sh] if t >= 2 * sh else s[0]
                a3 = s[t - 3 * sh] if t >= 3 * sh else s[0]
                a4 = s[t - 4 * sh] if t >= 4 * sh else s[0]
                cur[t] = (a0 + 4.0 * a1 + 6.0 * a2 + 4.0 * a3 + a4) / 16.0
        else:
            for t in range(n):
                a1 = s[t - sh] if t >= sh else s[0]
                cur[t] = 0.5 * (s[t] + a1)
        det[j] = [s[t] - cur[t] for t in range(n)]
        s = cur

    ctx.S = s
    sets = {"23": (2, 3), "34": (3, 4), "345": (3, 4, 5)}
    which = tuple(j for j in sets.get(str(ctx.p.detail_set), (3, 4)) if j <= lv)
    if not which:
        which = (lv,)
    M = [0.0] * n
    for t in range(n):
        tot = 0.0
        for j in which:
            tot += det[j][t]
        M[t] = tot
    ctx.M = M

    w = int(ctx.p.pct_win)
    rank = [None] * n
    win = []
    for t in range(n):
        bisect.insort(win, M[t])
        if len(win) > w:
            old = M[t - w]
            k = bisect.bisect_left(win, old)
            if k < len(win) and win[k] == old:
                del win[k]
        if len(win) >= w:
            rank[t] = bisect.bisect_left(win, M[t]) / float(len(win))
    ctx.rank = rank

    span = (1 << lv) * (4 if wave == "b3" else 1)
    ctx.start = span + w + 2


def signal(ctx, i):
    if i < ctx.start:
        return 0
    r = ctx.rank[i]
    if r is None:
        return 0
    lo = float(ctx.p.p_lo) / 100.0
    hi = 1.0 - lo
    a, b = ctx.S[i], ctx.S[i - 1]
    if a > b and r <= lo:
        return 1
    if a < b and r >= hi:
        return -1
    return 0


def exit_signal(ctx, i):
    if i < 1:
        return False
    r = ctx.rank[i]
    if r is None:
        return False
    lo = float(ctx.p.p_lo) / 100.0
    hi = 1.0 - lo
    d = ctx._dir
    if d > 0:
        return r >= hi or ctx.S[i] < ctx.S[i - 1]
    if d < 0:
        return r <= lo or ctx.S[i] > ctx.S[i - 1]
    return False
